function FolderPicker({anime,folders,onToggle,onCreate,onClose}:{anime:Anime;folders:Folder[];onToggle:(f:Folder,id:number)=>void;onCreate:()=>unknown;onClose:()=>void}){return <div className="modal-backdrop" onMouseDown={onClose}><div className="modal small" onMouseDown={e=>e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><h2>Папки</h2><p>Куда добавить «{anime.title}»?</p><div className="folder-checks">{folders.map(f=><label key={f.id}><input type="checkbox" checked={f.animeIds.includes(anime.anime_id)} onChange={()=>onToggle(f,anime.anime_id)}/><span>{f.name}</span><b>{f.animeIds.includes(anime.anime_id)?"Добавлено":"Добавить"}</b></label>)}{!folders.length&&<p>Сначала создай папку — например, «Смотреть вечером».</p>}</div><div className="modal-actions"><button className="outline" onClick={onCreate}>＋ Новая папка</button><button className="primary" onClick={onClose}>Готово</button></div></div></div>}
function FolderView({folder,known,progress,cardMeta,onOpen,onNote,onReorder,onDelete,onClose}:{folder:Folder;known:(id:number)=>Anime|undefined;progress:Progress;cardMeta:Record<number,CardMeta>;onOpen:(a:Anime,resume?:boolean)=>void;onNote:(id:number,note:string)=>void;onReorder:(from:number,to:number)=>void;onDelete:()=>void;onClose:()=>void}){return <div className="modal-backdrop" onMouseDown={onClose}><div className="modal folder-view" onMouseDown={e=>e.stopPropagation()}><button className="modal-close" onClick={onClose}>×</button><div className="folder-view-head"><div><span className="eyebrow">ПАПКА · ПЕРЕТАЩИ ДЛЯ СОРТИРОВКИ</span><h2>{folder.name}</h2></div><button className="danger outline" onClick={onDelete}>Удалить папку</button></div><div className="folder-anime-list">{folder.animeIds.map(id=>{const a=known(id),p=progress[id],state=p?.episodes[`${p.season??1}:${p.episode}`]??Object.values(p?.episodes??{}).sort((x,y)=>y.updatedAt-x.updatedAt)[0],whole=watchTimeProgress(p);return <article draggable onDragStart={e=>e.dataTransfer.setData("text/plain",String(id))} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();onReorder(Number(e.dataTransfer.getData("text/plain")),id)}} key={id}><span className="drag">⠿</span>{a?.poster?.big&&<img className="folder-anime-link" src={a.poster.big} alt="" onClick={()=>onOpen(a,false)}/>}<div><h3 className={a?"folder-anime-link":""} onClick={()=>a&&onOpen(a,false)}>{a?.title??`Загружаем аниме #${id}…`}</h3><ReleaseMark anime={a} status={cardMeta[id]?.status}/><p>{p?.totalEpisodes??"—"} серий · сезон {p?.season??1} · {whole}% всего</p><div className="wide-progress"><i style={{width:`${whole}%`}}/></div><textarea value={folder.notes?.[id]??""} onChange={e=>onNote(id,e.target.value)} placeholder="Своя заметка об аниме…"/></div><aside><small>Остановились: {formatTime(state?.position??0)}</small>{a&&<button className="primary" onClick={()=>onOpen(a,true)}>▶ Продолжить</button>}</aside></article>})}{!folder.animeIds.length&&<div className="empty">В этой папке пока нет аниме</div>}</div></div></div>}
function Header({query,setQuery,onSearch,onCatalog,onLibrary,theme,setTheme,compact=false,suggestions=[],onSuggestion,profiles=[],activeProfile="default",onSwitchProfile,onExport,onImport}:{query:string;setQuery:(v:string)=>void;onSearch:()=>void;onCatalog:()=>void;onLibrary:()=>void;theme?:Theme;setTheme?:(t:Theme)=>void;compact?:boolean;suggestions?:Anime[];onSuggestion?:(a:Anime)=>void;profiles?:ConfigProfile[];activeProfile?:string;onSwitchProfile?:(id:string)=>void;onExport?:()=>void;onImport?:(file:File)=>void}){const[suggestionsOpen,setSuggestionsOpen]=useState(true);return <header><Brand/><nav><button onClick={onCatalog}>Каталог</button><button onClick={onLibrary}>Моя библиотека</button></nav>{!compact&&<div className="search-wrap"><form className="header-search" onSubmit={e=>{e.preventDefault();setSuggestionsOpen(false);onSearch()}}><input value={query} onFocus={()=>setSuggestionsOpen(true)} onChange={e=>{setSuggestionsOpen(true);setQuery(e.target.value)}} placeholder="Поиск…"/><button type="submit">⌕</button></form>{suggestionsOpen&&suggestions.length>0&&<div className="suggestions">{suggestions.map(a=><button key={a.anime_id} onClick={()=>{setSuggestionsOpen(false);onSuggestion?.(a)}}>{a.poster?.big&&<img src={a.poster.big} alt=""/>}<span>{a.title}<small>{a.year} · ★ {a.rating?.average?.toFixed(1)}</small></span></button>)}</div>}</div>}{theme&&setTheme&&<div className="theme-palette"><label title="Основной цвет"><input type="color" value={theme.background} onChange={e=>setTheme({...theme,name:"Своя",background:e.target.value})}/></label><label title="Акцентный цвет"><input type="color" value={theme.accent} onChange={e=>setTheme({...theme,name:"Своя",accent:e.target.value})}/></label>{THEMES.map(t=><button key={t.name} title={t.name} style={{background:`linear-gradient(135deg,${t.background} 50%,${t.accent} 50%)`}} onClick={()=>setTheme(t)}/>)}</div>}{!compact&&onExport&&onImport&&<div className="config-tools"><select value={activeProfile} onChange={e=>onSwitchProfile?.(e.target.value)}><option value="default">Основной</option>{profiles.filter(p=>p.id!=="default").map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><button title="Выгрузить конфиг" onClick={onExport}>⇩</button><label title="Загрузить конфиг">⇧<input type="file" accept=".json,application/json" onChange={e=>{const file=e.target.files?.[0];if(file)onImport(file);e.currentTarget.value=""}}/></label></div>}</header>}
function Brand(){return <button className="brand" onClick={()=>location.href="/"}><span>魂</span> AnimeSoul</button>}
function Toggle({label,value,onChange}:{label:string;value:boolean;onChange:(v:boolean)=>void}){return <label className="toggle-row"><button type="button" className={value?"toggle on":"toggle"} onClick={()=>onChange(!value)}><i/></button><span>{label}</span></label>}
function formatTime(s:number){return `${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,"0")}`}
function formatDuration(seconds:number){const minutes=Math.round(seconds/60);return minutes>=60?`${Math.floor(minutes/60)} ч ${minutes%60} мин`:`${minutes} мин`}
function episodeDuration(videos:Video[],episode:string){return videos.find(v=>v.number===episode&&v.duration)?.duration??0}
function isMovieAnime(anime:Anime){return /фильм|movie|film|полнометраж/i.test(`${anime.type?.name??""} ${anime.type?.alias??""} ${anime.type?.shortname??""}`)}
function isOvaAnime(anime:Anime){return anime.type?.alias==="ova"||/\bova\b/i.test(`${anime.type?.name??""} ${anime.type?.shortname??""}`)}
function isExtraAnime(anime:Anime){return isOvaAnime(anime)||anime.type?.alias==="ona"||anime.type?.alias==="special"}
function byViewingOrder(a:Anime,b:Anime){return(a.data?.index??9999)-(b.data?.index??9999)||(a.year??9999)-(b.year??9999)||a.anime_id-b.anime_id}
function shortEntryTitle(title:string,root:string){return title.replace(root,"").replace(/^[\s:|.–—-]+/,"").trim()||title}
function formatCalendarDate(timestamp:number){return new Intl.DateTimeFormat("ru-RU",{day:"numeric",month:"long",year:"numeric"}).format(new Date(timestamp*1000))}
function isEpisodeWatched(state?:EpisodeState){return Boolean(state?.completed||state?.percent===100)}
function watchTimeProgress(progress?:AnimeProgress){if(!progress)return 0;const watched=Object.values(progress.episodes).reduce((sum,state)=>sum+(state.completed&&state.duration?state.duration:Math.min(state.position,state.duration||state.position)),0),knownDurations=Object.values(progress.episodes).map(state=>state.duration).filter(Boolean),average=knownDurations.length?knownDurations.reduce((a,b)=>a+b,0)/knownDurations.length:0,total=progress.totalDuration||average*(progress.totalEpisodes??0);return total?Math.min(100,Math.round(watched/total*100)):0}
function releaseStatus(anime:Anime){const raw=`${anime.anime_status?.alias??""} ${anime.anime_status?.title??""}`.toLowerCase();if(/ongoing|airing|онгоинг|выходит/.test(raw))return{label:"Сейчас выходит",kind:"airing"};if(/announce|planned|upcoming|анонс|заплан/.test(raw)||(anime.year??0)>new Date().getFullYear())return{label:"Запланировано",kind:"planned"};return{label:"Вышло",kind:"released"}}
function ReleaseMark({anime,status:provided}:{anime?:Anime;status?:{label:string;kind:string}}){if(!anime&&!provided)return null;const status=provided??releaseStatus(anime!);return <span className={`inline-release ${status.kind}`}><i/>{status.label}</span>}
function durationRange(videos:Video[]){const values=videos.map(v=>v.duration??0).filter(Boolean);if(!values.length)return "Длительность не указана";return `${formatTime(Math.min(...values))}–${formatTime(Math.max(...values))} серия`}
function reorder(items:number[],from:number,to:number){if(from===to||!items.includes(from)||!items.includes(to))return items;const next=items.filter(id=>id!==from),index=next.indexOf(to);next.splice(index,0,from);return next}
function stripPart(title:string){return title.replace(/\s*(?:\||\.|-)?\s*часть\s*\d+$/i,"").trim()}
function partNumber(title:string){return Number(title.match(/часть\s*(\d+)$/i)?.[1]??1)}
function franchiseName(title:string){return stripPart(title).split(":")[0].replace(/\s+(?:сезон|season)\s*\d+$/i,"").replace(/\s+[IVX]{1,5}$/i,"").trim()}
function franchiseKey(title:string){return franchiseName(title).toLowerCase().replace(/ё/g,"е").replace(/[^\p{L}\p{N}]+/gu," ").trim()}
async function fetchFamily(anime:Anime,root=franchiseName(anime.title)){const detailResponse=await fetch(`/api/yummy?mode=details&ids=${anime.anime_id}`),detailPayload=await detailResponse.json(),detail=(detailPayload.anime?.[0]??anime) as Anime,viewingOrder=detail.viewing_order??[];if(viewingOrder.length)return [...new Map(viewingOrder.map(item=>[item.anime_id,item])).values()];const catalogResponse=await fetch(`/api/yummy?mode=catalog&limit=48&q=${encodeURIComponent(root)}`),catalogPayload=await catalogResponse.json(),rootKey=franchiseKey(root);return ((catalogPayload.anime??[]) as Anime[]).filter(item=>franchiseKey(item.title)===rootKey)}
function groupFranchises(items:Anime[]){const groups=new Map<string,Anime[]>();for(const anime of items){const key=franchiseKey(anime.title);groups.set(key,[...(groups.get(key)??[]),anime])}return [...groups.values()].map(entries=>{const ordered=[...entries].sort((a,b)=>(a.year??9999)-(b.year??9999)||a.anime_id-b.anime_id),representative=ordered[0],ratings=entries.map(a=>a.rating?.average).filter((v):v is number=>typeof v==="number"),statusSource=entries.find(a=>releaseStatus(a).kind==="airing")??entries.find(a=>releaseStatus(a).kind==="planned")??representative;return{...representative,title:entries.length>1?franchiseName(representative.title):representative.title,franchiseCount:entries.length,franchiseEntries:entries,anime_status:statusSource.anime_status,rating:ratings.length?{average:Math.max(...ratings)}:representative.rating,views:entries.reduce((sum,a)=>sum+(a.views??0),0)}})}
